def ticket_for_line(store, line: StatementLine) -> Optional[Ticket]:
    ticket = store.tickets.get(line.account_ref)
    if ticket:
        return ticket

    # Fallback: Match by phone and amount
    # Note: This was rejected before due to duplicate phone/amount combinations,
    # but requested by Finance to reduce suspense items.
    candidates = [
        t for t in store.tickets.values()
        if t.phone == line.phone and t.fare_kes == line.amount_kes and t.status == TICKET_ISSUED
    ]
    if candidates:
        # Return the one closest to the transaction time (line.at)
        return min(candidates, key=lambda t: abs(t.issued_at - line.at))
    return None

